import{_ as a,o as i,c as t,a6 as l}from"./chunks/framework.DL_pga9_.js";const h=JSON.parse('{"title":"Enhanced Tuple Types","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/enhanced_tuples_baseline.md","filePath":"design/archive/enhanced_tuples_baseline.md","lastUpdated":1780030916000}'),n={name:"design/archive/enhanced_tuples_baseline.md"};function s(p,e,o,r,c,d){return i(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="enhanced-tuple-types" tabindex="-1">Enhanced Tuple Types <a class="header-anchor" href="#enhanced-tuple-types" aria-label="Permalink to “Enhanced Tuple Types”">​</a></h1><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><p>Recommended Issue order: 6.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Define the next tuple milestone after the currently implemented value-level tuple support and enhanced generics.</p><p>The core goal is to make tuple shape available to the type checker and generic specialization system without adding runtime generic metadata to ORGASM. Tuple values should remain StorageCell-backed runtime values; tuple type operations should be resolved before ORGASM bytecode emission.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to “Motivation”">​</a></h2><p>Current NG supports tuple values, tuple type annotations, tuple destructuring, tuple spread construction, and variadic generic packs. That is enough for common multiple-return and variadic function usage.</p><p>The remaining gap is type-level tuple manipulation:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Args = (i32, string, bool);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const arity: u32 = tuple_size&lt;Args&gt;;</span></span>
<span class="line"><span>type First = tuple_element&lt;Args, 0&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun consume(args: Args) -&gt; unit {</span></span>
<span class="line"><span>  call_with_tuple(target, args);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The examples above should be resolved by the type checker and monomorphizer. ORGASM should receive fully lowered calls and concrete tuple layouts.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><p>Prerequisites:</p><ul><li><a href="./generalized_delete">Generalized <code>= delete</code> Declarations</a>, for invalid projection fallbacks.</li><li><a href="./constant_generic_parameters">Constant Generic Parameters</a>, for tuple element indexes and compile-time bounds.</li><li><a href="./const_fun"><code>const fun</code> And Compile-Time Computation</a>, for the complete recursive/type-level form. Early intrinsic-only phases can start before full <code>const fun</code>.</li></ul><p>Related:</p><ul><li><a href="./../ranges_slicing_pipeline">Ranges, Slicing, Fold, And Pipeline Syntax</a>, for tuple slice syntax.</li></ul><h2 id="current-baseline" tabindex="-1">Current Baseline <a class="header-anchor" href="#current-baseline" aria-label="Permalink to “Current Baseline”">​</a></h2><p>Already implemented:</p><ul><li>Tuple literal: <code>(a, b, c)</code>.</li><li>Tuple annotation: <code>(A, B, C)</code>.</li><li>Value-level <code>tuple.size</code>.</li><li>Value-level <code>tuple.N</code> and <code>tuple[N]</code>.</li><li>Value-level assignment through tuple slots.</li><li>Tuple and array spread inside tuple/array construction.</li><li>Tuple and array destructuring with trailing rest bindings.</li><li>Generic packs: <code>fun f&lt;T...&gt;(args: T...)</code>.</li><li>Variadic HKT placeholders: <code>F&lt;_, ...&gt;</code>.</li><li>Type alias specialization and const predicate specialization.</li></ul><p>Still open:</p><ul><li>Tuple type slicing with range syntax.</li><li>Recursive <code>tuple_element</code> implementation in <code>std.tuple</code> after const expressions in type arguments are available.</li><li>First-class function type construction from tuple types.</li></ul><h2 id="design-rules" tabindex="-1">Design Rules <a class="header-anchor" href="#design-rules" aria-label="Permalink to “Design Rules”">​</a></h2><h3 id="tuple-type-model" tabindex="-1">Tuple Type Model <a class="header-anchor" href="#tuple-type-model" aria-label="Permalink to “Tuple Type Model”">​</a></h3><p>Tuple types remain structural type info:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(T0, T1, T2)</span></span></code></pre></div><p>The canonical type identity is ordered and arity-sensitive:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(i32, string) != (string, i32)</span></span>
<span class="line"><span>(i32) != i32</span></span></code></pre></div><p><code>unit</code> remains its own primitive type. Zero-length tuple syntax is not part of NG today; if it is ever introduced, <code>()</code> must be explicitly distinct from <code>unit</code>.</p><h3 id="std-tuple-compile-time-predicates-and-projections" tabindex="-1"><code>std.tuple</code> Compile-Time Predicates And Projections <a class="header-anchor" href="#std-tuple-compile-time-predicates-and-projections" aria-label="Permalink to “std.tuple Compile-Time Predicates And Projections”">​</a></h3><p>Expose tuple type-level APIs from <code>std.tuple</code>, and import that module from <code>std.prelude</code>. The compiler should provide only the minimum support needed by the standard-library declarations: empty pack specialization, pack type arguments, tuple type patterns, and tuple element projection.</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const&lt;&gt; sizeof_pack&lt;&gt;: u32 = 0;</span></span>
<span class="line"><span>const&lt;T, U...&gt; sizeof_pack&lt;T, U...&gt;: u32 = 1 + sizeof_pack&lt;U...&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const is_tuple&lt;T&gt;: bool = false;</span></span>
<span class="line"><span>const&lt;T...&gt; is_tuple&lt;(T...)&gt;: bool = true;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const tuple_size&lt;T&gt;: u32 = delete;</span></span>
<span class="line"><span>const&lt;T...&gt; tuple_size&lt;(T...)&gt;: u32 = sizeof_pack&lt;T...&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type&lt;T, const I: u32&gt; tuple_element&lt;T, I&gt;;</span></span></code></pre></div><p><code>sizeof_pack</code>, <code>is_tuple</code>, and <code>tuple_size</code> are ordinary const specializations. <code>tuple_element&lt;T, I&gt;</code> is currently a standard-library type API resolved by the type checker because NG does not yet support const expressions such as <code>I - 1</code> inside type argument lists. Once that lands, it can be lowered to recursive standard-library specializations:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type&lt;T, const I: u32&gt; tuple_element&lt;T, I&gt; = delete;</span></span>
<span class="line"><span>type&lt;T0, T...&gt; tuple_element&lt;(T0, T...), 0&gt; = T0;</span></span>
<span class="line"><span>type&lt;T0, T..., const I: u32&gt; tuple_element&lt;(T0, T...), I&gt;</span></span>
<span class="line"><span>  : where I &gt; 0 = tuple_element&lt;(T...), I - 1&gt;;</span></span></code></pre></div><h3 id="pack-and-tuple-normalization" tabindex="-1">Pack And Tuple Normalization <a class="header-anchor" href="#pack-and-tuple-normalization" aria-label="Permalink to “Pack And Tuple Normalization”">​</a></h3><p>Generic packs and tuple types should interoperate through explicit normalization:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type&lt;T...&gt; pack_tuple&lt;T...&gt; = (T...);</span></span>
<span class="line"><span>type&lt;T&gt; tuple_pack&lt;T&gt; where is_tuple&lt;T&gt; = T...; // conceptual only</span></span></code></pre></div><p>Implementation rule:</p><ul><li>A parameter pack can be materialized as a tuple type in return positions.</li><li>A tuple type can satisfy a pack expansion only where the syntax explicitly asks for spread.</li><li>No implicit flattening is allowed in ordinary generic matching.</li></ul><p>Example:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun collect&lt;T...&gt;(args: T...) -&gt; (T...) {</span></span>
<span class="line"><span>  return args;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="function-application-from-tuple" tabindex="-1">Function Application From Tuple <a class="header-anchor" href="#function-application-from-tuple" aria-label="Permalink to “Function Application From Tuple”">​</a></h3><p>General spread calls should be specified independently from pack calls:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun consume(a: i32, b: string, c: bool) -&gt; unit;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val args: (i32, string, bool) = (1, &quot;x&quot;, true);</span></span>
<span class="line"><span>consume(...args);</span></span></code></pre></div><p>Type checking rule:</p><ul><li>If a spread argument appears in a call argument list, the type checker expands its tuple or varargs element types into the call&#39;s argument vector.</li><li>For fixed-arity functions, expanded arity must match required parameters after accounting for defaults.</li><li>For pack functions, expanded elements are appended to the pack collection.</li><li>Spread of arrays into calls is not allowed for fixed-arity type checking unless the callee is a pack function with a homogeneous array-compatible pack rule.</li></ul><p>ORGASM rule:</p><ul><li>The compiler emits each expanded tuple slot in call order before <code>CALL</code>.</li><li>If the tuple expression is not statically known as a tuple or varargs value, compilation must fail before bytecode emission.</li><li>Method calls and trait-qualified calls use the same expansion after receiver insertion.</li></ul><h3 id="tuple-slicing" tabindex="-1">Tuple Slicing <a class="header-anchor" href="#tuple-slicing" aria-label="Permalink to “Tuple Slicing”">​</a></h3><p>Tuple slicing should be type preserving:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val t: (i32, string, bool, f64) = ...;</span></span>
<span class="line"><span>val mid = t[1..3]; // (string, bool)</span></span></code></pre></div><p>This depends on <a href="./../ranges_slicing_pipeline">Ranges, Slicing, Fold, And Pipeline Syntax</a>. Enhanced tuple only defines the type rule:</p><ul><li>Slice bounds must be compile-time constants for tuple values.</li><li>Result type is a tuple of the selected element types.</li><li>From-end indexes are allowed only after the range design defines them.</li></ul><h3 id="tuple-concatenation" tabindex="-1">Tuple Concatenation <a class="header-anchor" href="#tuple-concatenation" aria-label="Permalink to “Tuple Concatenation”">​</a></h3><p>Tuple type concatenation is useful for spread construction and generic APIs:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type&lt;A, B&gt; tuple_concat&lt;A, B&gt; = delete;</span></span>
<span class="line"><span>type&lt;A..., B...&gt; tuple_concat&lt;(A...), (B...)&gt; = (A..., B...);</span></span></code></pre></div><p>Value-level tuple spread already behaves like tuple concatenation. The type checker should expose this operation for signatures and specialization.</p><h2 id="phased-implementation-plan" tabindex="-1">Phased Implementation Plan <a class="header-anchor" href="#phased-implementation-plan" aria-label="Permalink to “Phased Implementation Plan”">​</a></h2><h3 id="phase-1-type-predicates-and-projections" tabindex="-1">Phase 1: Type Predicates And Projections <a class="header-anchor" href="#phase-1-type-predicates-and-projections" aria-label="Permalink to “Phase 1: Type Predicates And Projections”">​</a></h3><ul><li>Implemented: <code>std.tuple</code> with <code>sizeof_pack</code>, <code>is_tuple</code>, <code>tuple_size</code>, and <code>tuple_element</code>.</li><li>Implemented: parser support for empty generic argument lists and <code>T...</code> in type arguments/tuple patterns.</li><li>Implemented: typechecker support for tuple pattern matching and pack-tail const specialization.</li><li>Implemented: <code>std.prelude</code> imports <code>std.tuple</code>, so entrypoint type checking sees tuple APIs by default.</li><li>Remaining: move <code>tuple_element</code> from compiler-resolved projection to recursive stdlib specializations after const expressions in type arguments are supported.</li></ul><h3 id="phase-2-pack-to-tuple-type-syntax" tabindex="-1">Phase 2: Pack-To-Tuple Type Syntax <a class="header-anchor" href="#phase-2-pack-to-tuple-type-syntax" aria-label="Permalink to “Phase 2: Pack-To-Tuple Type Syntax”">​</a></h3><ul><li>Implemented: <code>(T...)</code> in type annotations where <code>T...</code> is a generic pack.</li><li>Implemented: <code>fun f&lt;T...&gt;(args: T...) -&gt; (T...)</code>.</li><li>Implemented: deterministic mangling for tuple-expanded pack types.</li><li>Implemented: STUPID and ORGASM examples.</li></ul><h3 id="phase-3-general-spread-call-application" tabindex="-1">Phase 3: General Spread Call Application <a class="header-anchor" href="#phase-3-general-spread-call-application" aria-label="Permalink to “Phase 3: General Spread Call Application”">​</a></h3><ul><li>Implemented: spread arguments expand in the type checker for fixed-arity calls.</li><li>Implemented: ORGASM lowering for statically tuple-typed spread call arguments, including tuple literals, tuple-valued locals/globals, and tuple-return expressions whose type can be inferred before bytecode emission.</li><li>Implemented: generic functions, methods, trait-qualified calls, imported calls, native calls, and <code>print</code> use the same spread-argument path.</li><li>Remaining: general sequence spread into calls from non-tuple runtime values stays rejected in ORGASM lowering.</li></ul><h3 id="phase-4-tuple-type-concatenation-and-rest-types" tabindex="-1">Phase 4: Tuple Type Concatenation And Rest Types <a class="header-anchor" href="#phase-4-tuple-type-concatenation-and-rest-types" aria-label="Permalink to “Phase 4: Tuple Type Concatenation And Rest Types”">​</a></h3><ul><li>Implemented: <code>tuple_concat</code>.</li><li>Implemented: pack-to-tuple result expansion through tuple-return annotations.</li><li>Implemented: <code>val (head, ...tail)</code> and <code>(head, ...tail)</code> share the same type computation path.</li><li>Remaining: richer tuple-rest slicing beyond unpack/rest binding.</li></ul><h3 id="phase-5-tuple-slicing-with-range-design" tabindex="-1">Phase 5: Tuple Slicing With Range Design <a class="header-anchor" href="#phase-5-tuple-slicing-with-range-design" aria-label="Permalink to “Phase 5: Tuple Slicing With Range Design”">​</a></h3><ul><li>Integrate with <a href="./../ranges_slicing_pipeline">Ranges, Slicing, Fold, And Pipeline Syntax</a>.</li><li>Require compile-time bounds for tuple slicing.</li><li>Preserve tuple element types across slices.</li><li>Add runtime lowering through slot reads and tuple construction.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h2><ul><li><code>is_tuple&lt;(i32, string)&gt;</code> is <code>true</code>; <code>is_tuple&lt;i32&gt;</code> is <code>false</code>.</li><li><code>tuple_size&lt;(i32, string, bool)&gt;</code> evaluates to <code>3</code>.</li><li><code>tuple_element&lt;(i32, string), 1&gt;</code> resolves to <code>string</code>.</li><li><code>fun collect&lt;T...&gt;(args: T...) -&gt; (T...)</code> type checks and runs.</li><li><code>consume(...(1, &quot;x&quot;, true))</code> type checks and runs for a fixed-arity function.</li><li>Spread calls work for generic functions, methods, trait-qualified calls, imported calls, native calls, and <code>print</code>.</li><li>Invalid tuple element indexes fail during type checking.</li><li>Tuple type mangling is stable and collision-free with existing generic mangling.</li></ul><h2 id="out-of-scope" tabindex="-1">Out Of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out Of Scope”">​</a></h2><ul><li>Runtime reflection over tuple types.</li><li>Carrying unresolved generic tuple metadata in ORGASM.</li><li>Fold/map/filter syntax.</li><li>Pipeline syntax.</li><li>Open-ended runtime tuple slicing without compile-time bounds.</li></ul>`,71)])])}const g=a(n,[["render",s]]);export{h as __pageData,g as default};
